refentry.refsect1:
&reftitle.description;

 public arrayYaf_Config_Ini::toArray


Returns the entire configuration as a plain PHP array.

  &reftitle.examples;

   Yaf_Config_Ini::toArray example


<?php
/**
 * Assume /etc/myapp/application.ini contains:
 * [common]
 * application.name = "MyApp"
 * database.host    = "localhost"
 * database.port    = 3306
 */
$config = new Yaf_Config_Ini('/etc/myapp/application.ini', 'common');

print_r($config->toArray());
?>


   &example.outputs.similar;


Array
(
    [application] => Array
        (
            [name] => MyApp
        )

    [database] => Array
        (
            [host] => localhost
            [port] => 3306
        )

)
